rg -n --glob '*.test.ts' 'CURRENT_VERSION|"s".*split|\bs: "split"|\["s"' classic/apps/web/src/actions; cat > classic/apps/web/src/actions/keybindings/__tests__/start-end.test.ts <<'TS'
import { expect, test } from "bun:test";
import { getDefaultKeybindings } from "@/actions/definitions";
import { v8ToV9 } from "../migrations/v8-to-v9";
test("Start End migrates S/E and preserves custom bindings", () => {
 expect(v8ToV9({state:{keybindings:{s:"split"},isCustomized:false}})).toEqual({keybindings:{s:"trim-start",e:"trim-end","shift+s":"split"},isCustomized:false});
 expect(v8ToV9({state:{keybindings:{s:"undo",e:"redo","shift+s":"copy-selected"},isCustomized:true}})).toEqual({keybindings:{s:"undo",e:"redo","shift+s":"copy-selected"},isCustomized:true});
});
TS
rg -n 'export function|export const' classic/apps/web/src/actions/definitions.ts | tail -5
bun run --cwd classic/apps/web test src/actions/keybindings/__tests__ > /tmp/start-end-web.log 2>&1

